def find_max_diff(nums):
    if len(nums) == 0:
        return None
    max_diff = nums[1] - nums[0]
    for i in range(2, len(nums) - 1):
        diff = nums[i] - nums[i-1]
        if diff > max_diff:
            max_diff = diff
    return max_diff
